/**
 * @softimist/api - React Hooks for API interactions
 *
 * Generic hooks that work with any HttpClient implementation
 */
'use client';

import { useQuery, useMutation, type QueryKey, type UseQueryOptions } from '@tanstack/react-query';
import { createParser, parseAsInteger, parseAsString, useQueryState } from 'nuqs';
import { useState } from 'react';
import { toast } from 'sonner';
import type {
	HttpClient,
	PaginationOptions,
	ServerPaginatedResponse,
	ServerResponse,
	UsePaginatedApiReturn,
} from './types';
import type { Filter } from './filter';
import { getQueryClient } from './tanstack-query';

/**
 * Hook for making simple API GET requests
 */
export function useApi<T>(
	httpClient: HttpClient,
	url: string | null,
	options: Omit<UseQueryOptions<ServerResponse<T>>, 'queryKey' | 'queryFn' | 'enabled'> & {
		queryKey?: QueryKey;
		enabled?: boolean;
	} = {},
) {
	const { queryKey, enabled = true, ...restOptions } = options;

	return useQuery<ServerResponse<T>>({
		queryKey: queryKey || [url],
		queryFn: async () => {
			if (!url) throw new Error('URL is required');
			return httpClient.get<ServerResponse<T>>(url);
		},
		enabled: url !== null && enabled,
		...restOptions,
	});
}

/**
 * Hook for making API mutations (POST, PATCH, PUT, DELETE) with toast notifications
 *
 * @template T - The response data type
 * @template TArg - The argument type for the action (defaults to void for backward compatibility)
 */
export function useApiAction<T, TArg = void>(
	options: {
		action: (arg: TArg) => Promise<ServerResponse<T>>;
		showToast?: boolean;
		invalidateQueries?: QueryKey[];
		onSuccess?: (data: T) => void;
		onError?: (error: Error) => void;
	},
) {
	const { action, showToast = true, invalidateQueries, onSuccess, onError } = options;

	const mutation = useMutation({
		mutationFn: action,

		onSuccess: (res) => {
			onSuccess?.(res.data);
			if (showToast) {
				toast.success(res.message || 'Success');
			}
			if (invalidateQueries && invalidateQueries.length > 0) {
				const queryClient = getQueryClient();
				invalidateQueries.forEach((queryKey) => {
					queryClient.invalidateQueries({ queryKey });
				});
			}
		},
		onError: (err: Error) => {
			onError?.(err);
			if (showToast) {
				toast.error(err.message || 'An error occurred');
			}
		},
	});

	return {
    /** execute mutation */
    execute: mutation.mutate,

    /** async version if needed */
    executeAsync: mutation.mutateAsync,

    /** states */
    isLoading: mutation.isPending,
    isSuccess: mutation.isSuccess,
    isError: mutation.isError,
    isExecuted: mutation.status !== 'idle',

    /** data & error */
    data: mutation.data?.data,
    error: mutation.error ?? undefined,

    /** reset to idle */
    reset: mutation.reset,
  };
}

const parseAsFilterArray = createParser<Filter[]>({
	parse: (value) => {
		return JSON.parse(value);
	},
	serialize: (value) => {
		return JSON.stringify(value);
	},
});

function usePaginationState(options: PaginationOptions) {
	const { persist = true, params: defaultParams } = options;
	const defaultPerPage = (defaultParams?.per_page as number) || 20;
	const defaultPage = (defaultParams?.page as number) || 1;
	const [perPageQuery, setPerPageQuery] = useQueryState(
		'per_page',
		parseAsInteger.withDefault(defaultPerPage),
	);
	const [pageQuery, setPageQuery] = useQueryState('page', parseAsInteger.withDefault(defaultPage));
	const [searchQuery, setSearchQuery] = useQueryState('search', parseAsString.withDefault(''));
	const [filtersQuery, setFiltersQuery] = useQueryState(
		'filters',
		parseAsFilterArray.withDefault([]),
	);
	const [sortQuery, setSortQuery] = useQueryState('sort', parseAsString.withDefault(''));

	const [perPageState, setPerPageState] = useState<number>(defaultPerPage);
	const [pageState, setPageState] = useState<number>(defaultPage);
	const [searchState, setSearchState] = useState<string>('');
	const [filtersState, setFiltersState] = useState<Filter[]>([]);
	const [sortState, setSortState] = useState<string>();

	const perPage = persist ? perPageQuery : perPageState;
	const page = persist ? pageQuery : pageState;
	const search = persist ? searchQuery : searchState;
	const filters = persist ? filtersQuery : filtersState;
	const sort = persist ? sortQuery : sortState;

	const setPerPage = (value: number | ((prev: number) => number)) => {
		if (persist) {
			setPerPageQuery(value);
		} else {
			setPerPageState(value);
		}
	};

	const setPage = (value: number | ((prev: number) => number)) => {
		if (persist) {
			setPageQuery(value);
		} else {
			setPageState(value);
		}
	};

	const setSearch = (value: string | ((prev: string) => string)) => {
		if (persist) {
			setSearchQuery(value);
		} else {
			setSearchState(value);
		}
	};

	const setFilters = (value: Filter[] | ((prev: Filter[]) => Filter[])) => {
		if (persist) {
			setFiltersQuery(value);
		} else {
			setFiltersState(value);
		}
	};

	const setSort = (value: string | ((prev: string) => string)) => {
		if (persist) {
			setSortQuery(value);
		} else {
			setSortState(typeof value === 'function' ? value(sortState || '') : value);
		}
	};

	const getParams = () => {
		const params = new URLSearchParams();
		if (defaultParams) {
			Object.entries(defaultParams).forEach(([key, value]) => {
				if (value !== undefined) {
					params.set(key, value.toString());
				}
			});
		}
		if (perPage) params.set('per_page', perPage.toString());
		if (page) params.set('page', page.toString());
		if (search) params.set('search', search);
		if (sort) {
			const [sortBy, sortDirection] = sort.split(':');
			if (sortBy) params.set('sort_by', sortBy);
			if (sortDirection) params.set('sort_dir', sortDirection);
		}
		filters?.forEach((filter) => {
			if (Array.isArray(filter.value)) {
				filter.value.forEach((v) => {
					params.append(filter.key, v.toString());
				});
			} else {
				params.set(filter.key, filter.value.toString());
			}
		});
		return params;
	};

	return {
		perPage,
		page,
		search,
		filters,
		sort,
		setPerPage,
		setPage,
		setSearch,
		setFilters,
		setSort,
		getParams,
	};
}

/**
 * Hook for making paginated API requests with URL state management
 */
export function usePaginatedApi<T>(
	httpClient: HttpClient,
	path: string | null,
	options: PaginationOptions = {},
): UsePaginatedApiReturn<T> {
	const {
		perPage,
		page,
		search,
		filters,
		sort,
		setPerPage,
		setPage,
		setSearch,
		setFilters,
		setSort,
		getParams,
	} = usePaginationState(options);

	const getUrl = (): string | null => {
		if (!path) return null;
		const params = getParams();
		return params.size === 0 ? path : `${path}?${params.toString()}`;
	};

	const url = getUrl();

	const { data, isLoading, error, refetch, isSuccess, isFetching } = useQuery({
		queryKey: [path, options, page, perPage, search, filters, sort],
		queryFn: async () => {
			if (!url) throw new Error('URL is required');
			return httpClient.get<ServerPaginatedResponse<T>>(url);
		},
		enabled: !!url,
	});

	function getBulkActionUrl(
		action: string,
		additionalFilters?: Record<string, string | string[]>,
	): string {
		const params = getParams();
		params.delete('page');
		params.delete('per_page');
		Object.entries(additionalFilters || {}).forEach(([key, value]) => {
			if (value === undefined) {
				params.delete(key);
			} else if (Array.isArray(value)) {
				value.forEach((v) => {
					params.append(key, v);
				});
			} else {
				params.set(key, value);
			}
		});
		if (params.size === 0) return `${path}/${action}`;
		return `${path}/${action}?${params.toString()}`;
	}

	function setFilter(key: string, value: any) {
		if (value === undefined) {
			removeFilter(key);
			return;
		}
		const index = filters.findIndex((filter) => filter.key === key);
		if (index === -1) {
			setFilters([...filters, { key, value }]);
		} else {
			setFilters([...filters.slice(0, index), { key, value }, ...filters.slice(index + 1)]);
		}
	}

	function removeFilter(key: string) {
		setFilters(filters.filter((filter) => filter.key !== key));
	}

	function getFilterValue(key: string) {
		return filters.find((filter) => filter.key === key)?.value;
	}

	function resetFilters() {
		setFilters([]);
	}

	return {
		message: data?.message || '',
		data: data?.data || [],
		pagination: data?.pagination,
		isLoading,
		isSuccess,
		isFetching,
		error: error as Error | null,
		mutate: refetch,
		page,
		setPage,
		perPage,
		setPerPage,
		search,
		setSearch,
		filters,
		setFilters,
		setFilter,
		removeFilter,
		getFilterValue,
		resetFilters,
		getBulkActionUrl,
		sort,
		setSort,
	};
}

/**
 * Mock hook for testing/development
 * Returns a mock paginated response with the provided data
 */
export function useMockPaginatedApi<T>(data: T[]): UsePaginatedApiReturn<T> {
	return {
		data,
		pagination: {
			total: data.length,
			per_page: 10,
			current_page: 1,
			total_pages: Math.ceil(data.length / 10),
			from: 1,
			to: data.length,
		},
		message: 'Data fetched successfully',
		isLoading: false,
		isSuccess: true,
		isFetching: false,
		mutate: () => {},
		page: 1,
		setPage: () => {},
		perPage: 10,
		setPerPage: () => {},
		search: '',
		setSearch: () => {},
		filters: [],
		setFilters: () => {},
		getFilterValue: () => undefined,
		resetFilters: () => {},
		setFilter: () => {},
		removeFilter: () => {},
		sort: '',
		setSort: () => {},
		getBulkActionUrl: () => '',
	};
}
