/**
 * @softimist/api - Base API Client
 *
 * Base class for API clients that can be extended by module-specific implementations.
 * Uses axios for HTTP requests and provides common functionality like authentication,
 * error handling, and request/response interceptors.
 *
 * All HTTP methods return unwrapped server response data directly (e.g., ServerResponse<T>).
 */

import axios, { AxiosResponse, type AxiosInstance, type AxiosRequestConfig } from 'axios';
import type { HttpClient } from './types';

/**
 * Configuration options for BaseApiClient
 */
export interface BaseApiClientConfig {
	baseURL?: string;
	getAuthToken?: () => string | null;
	getRefreshToken?: () => string | null;
	setAuthToken?: (token: string) => void;
	setRefreshToken?: (token: string) => void;
	clearAuthTokens?: () => void;
	refreshTokenUrl?: string;
	timeout?: number;
	headers?: Record<string, string>;
}

/**
 * Request configuration passed to HTTP methods
 */
export interface RequestConfig {
	headers?: Record<string, string>;
	params?: Record<string, any>;
	[key: string]: any;
}

/**
 * Base API Client class
 * Provides common HTTP functionality using axios that can be extended by module-specific clients
 *
 * @example
 * ```ts
 * class WebsiteApiClient extends BaseApiClient {
 *   async getPages(): Promise<ServerPaginatedResponse<Page>> {
 *     return this.get<ServerPaginatedResponse<Page>>('/api/v1/website/pages');
 *   }
 * }
 * ```
 */
export class BaseApiClient implements HttpClient {
	protected axiosInstance: AxiosInstance;
	protected getAuthToken?: () => string | null;
	protected getRefreshToken?: () => string | null;
	protected setAuthToken?: (token: string) => void;
	protected setRefreshToken?: (token: string) => void;
	protected clearAuthTokens?: () => void;
	protected refreshTokenUrl?: string;
	private isRefreshing = false;
	private failedQueue: Array<{
		resolve: (value?: any) => void;
		reject: (error?: any) => void;
	}> = [];

	constructor(config: BaseApiClientConfig = {}) {
		const defaultHeaders = {
			'Content-Type': 'application/json',
			Accept: 'application/json',
			...config.headers,
		};

		this.axiosInstance = axios.create({
			baseURL: config.baseURL || '',
			timeout: config.timeout || 30000,
			headers: defaultHeaders,
		});

		this.getAuthToken = config.getAuthToken;
		this.getRefreshToken = config.getRefreshToken;
		this.setAuthToken = config.setAuthToken;
		this.setRefreshToken = config.setRefreshToken;
		this.clearAuthTokens = config.clearAuthTokens;
		this.refreshTokenUrl = config.refreshTokenUrl || `${config.baseURL || ''}/v1/auth/refresh`;

		// Set up request interceptor for authentication
		this.axiosInstance.interceptors.request.use(
			(requestConfig) => {
				if (this.getAuthToken) {
					const token = this.getAuthToken();
					if (token) {
						requestConfig.headers.Authorization = `Bearer ${token}`;
					}
				}
				return requestConfig;
			},
			(error) => {
				return Promise.reject(error);
			},
		);

		// Set up response interceptor for error handling and token refresh
		this.axiosInstance.interceptors.response.use(
			(response) => response,
			async (error) => {
				const originalRequest = error.config;

				// Handle 401 errors with token refresh
				if (error.response?.status === 401 && !originalRequest._retry && this.getRefreshToken) {
					if (this.isRefreshing) {
						// If we're already refreshing, queue this request
						return new Promise((resolve, reject) => {
							this.failedQueue.push({ resolve, reject });
						})
							.then((token) => {
								originalRequest.headers.Authorization = `Bearer ${token}`;
								return this.axiosInstance(originalRequest);
							})
							.catch((err) => {
								return Promise.reject(err);
							});
					}

					originalRequest._retry = true;
					this.isRefreshing = true;

					try {
						const accessToken = await this.refreshAuthToken();

						// Update the original request with new token
						originalRequest.headers.Authorization = `Bearer ${accessToken}`;

						// Process queued requests
						this.processQueue(null, accessToken);
						this.isRefreshing = false;

						// Retry the original request
						return this.axiosInstance(originalRequest);
					} catch (refreshError) {
						// Refresh token is invalid, clear all tokens
						this.processQueue(refreshError, null);
						this.isRefreshing = false;
						return Promise.reject(this.handleError(refreshError));
					}
				}

				return Promise.reject(this.handleError(error));
			},
		);
	}

	/**
	 * Process queued requests after token refresh
	 */
	private processQueue(error: any, token: string | null = null) {
		this.failedQueue.forEach(({ resolve, reject }) => {
			if (error) {
				reject(error);
			} else {
				resolve(token);
			}
		});
		this.failedQueue = [];
	}

	/**
	 * Refresh authentication token
	 */
	private async refreshAuthToken(): Promise<string> {
		if (!this.getRefreshToken) {
			throw new Error('No refresh token function provided');
		}

		const refreshToken = this.getRefreshToken();
		if (!refreshToken) {
			if (this.clearAuthTokens) {
				this.clearAuthTokens();
			}
			throw new Error('No refresh token available');
		}

		try {
			// Use a fresh axios instance for refresh token request to avoid circular interceptor issues
			const response = await axios.post(
				this.refreshTokenUrl!,
				{
					refresh_token: refreshToken,
				},
				{
					baseURL: '', // Use absolute URL or empty to avoid baseURL duplication
				},
			);

			const { access_token, refresh_token } = response.data;

			if (this.setAuthToken) {
				this.setAuthToken(access_token);
			}
			if (refresh_token && this.setRefreshToken) {
				this.setRefreshToken(refresh_token);
			}

			return access_token;
		} catch (error) {
			// Refresh token is invalid, clear all tokens
			if (this.clearAuthTokens) {
				this.clearAuthTokens();
			}
			throw error;
		}
	}

	/**
	 * Handle request errors
	 */
	protected handleError(error: any): Error {
		if (error.response) {
			// Server responded with error status
			const message =
				error.response.data?.message ||
				error.response.data?.error ||
				error.message ||
				'An unknown error occurred';
			error.message = message;
			return error;
		}
		return error;
	}

	/**
	 * Make HTTP GET request
	 * Returns unwrapped server response data
	 */
	async get<T = any>(url: string, config?: RequestConfig): Promise<T> {
		const axiosConfig: AxiosRequestConfig = {
			params: config?.params,
			headers: config?.headers,
			...config,
		};
		delete axiosConfig.params;
		delete axiosConfig.headers;

		const response = await this.axiosInstance.get<T>(url, {
			...axiosConfig,
			params: config?.params,
			headers: config?.headers,
		});

		return response.data;
	}

	/**
	 * Make HTTP POST request
	 * Returns unwrapped server response data
	 */
	async post<T = any>(url: string, data?: any, config?: RequestConfig): Promise<T> {
		const axiosConfig: AxiosRequestConfig = {
			headers: config?.headers,
			...config,
		};
		delete axiosConfig.headers;

		const response = await this.axiosInstance.post<T>(url, data, {
			...axiosConfig,
			headers: config?.headers,
		});

		return response.data;
	}

	/**
	 * Make HTTP PATCH request
	 * Returns unwrapped server response data
	 */
	async patch<T = any>(url: string, data?: any, config?: RequestConfig): Promise<T> {
		const axiosConfig: AxiosRequestConfig = {
			headers: config?.headers,
			...config,
		};
		delete axiosConfig.headers;

		const response = await this.axiosInstance.patch<T>(url, data, {
			...axiosConfig,
			headers: config?.headers,
		});

		return response.data;
	}

	/**
	 * Make HTTP PUT request
	 * Returns unwrapped server response data
	 */
	async put<T = any>(url: string, data?: any, config?: RequestConfig): Promise<T> {
		const axiosConfig: AxiosRequestConfig = {
			headers: config?.headers,
			...config,
		};
		delete axiosConfig.headers;

		const response = await this.axiosInstance.put<T>(url, data, {
			...axiosConfig,
			headers: config?.headers,
		});

		return response.data;
	}

	/**
	 * Make HTTP DELETE request
	 * Returns unwrapped server response data
	 */
	async delete<T = any>(url: string, config?: RequestConfig): Promise<T> {
		const axiosConfig: AxiosRequestConfig = {
			headers: config?.headers,
			...config,
		};
		delete axiosConfig.headers;

		const response = await this.axiosInstance.delete<T>(url, {
			...axiosConfig,
			headers: config?.headers,
		});

		return response.data;
	}

	async export(
		url: string,
		config?: AxiosRequestConfig & {
			onDownloadProgress?: (event: ProgressEvent) => void;
		},
	): Promise<AxiosResponse<ArrayBuffer>> {
		return this.axiosInstance.get(url, {
			responseType: 'arraybuffer',
			...config,
		});
	}

	/**
	 * Get the underlying axios instance for advanced usage
	 */
	get axios(): AxiosInstance {
		return this.axiosInstance;
	}

	/**
	 * Create a new client instance with a different baseURL
	 * Useful for server-side requests or different API endpoints
	 */
	withBaseURL(baseURL: string): this {
		const ConfigClass = this.constructor as new (config: BaseApiClientConfig) => this;

		// Create a fresh copy of headers to avoid reference issues
		const headers = { ...this.axiosInstance.defaults.headers } as Record<string, string>;

		return new ConfigClass({
			baseURL,
			getAuthToken: this.getAuthToken,
			getRefreshToken: this.getRefreshToken,
			setAuthToken: this.setAuthToken,
			setRefreshToken: this.setRefreshToken,
			clearAuthTokens: this.clearAuthTokens,
			refreshTokenUrl: this.refreshTokenUrl,
			timeout: this.axiosInstance.defaults.timeout,
			headers,
		});
	}
}
