/**
 * @softimist/api - Utility Functions
 * 
 * Common utility functions for API error and response handling
 */

type ApiErrorLike = {
  message?: unknown;
  response?: {
    data?: {
      message?: unknown;
      error?: unknown;
    };
  };
};

/**
 * Extract error message from various error types
 */
export function getErrorMessage(error: unknown): string {
  const err = error as ApiErrorLike | null | undefined;
  
  // Try to get message from API response
  const apiMessage = err?.response?.data?.message;
  if (typeof apiMessage === 'string' && apiMessage.trim() !== '') {
    return apiMessage;
  }

  // Try to get error from API response
  const apiError = err?.response?.data?.error;
  if (typeof apiError === 'string' && apiError.trim() !== '') {
    return apiError;
  }

  // Try to get message from error object
  const message = err?.message;
  if (typeof message === 'string' && message.trim() !== '') {
    return message;
  }

  // Try Error instance message
  if (error instanceof Error && error.message.trim() !== '') {
    return error.message;
  }

  return 'Something went wrong';
}

/**
 * Extract success message from API response
 */
export function getSuccessMessage(response: any, defaultMessage?: string): string {
  return response?.data?.message || defaultMessage || 'Success';
}
